  @Override
  public int getSlots() {
    int totalSlots = 0;

    for (ICurioStacksHandler stacks : this.curioInventory.asMap().values()) {
      totalSlots += stacks.getSlots();
    }
    return totalSlots;
  }

  @Override
  public int getVisibleSlots() {
    int totalSlots = 0;

    for (ICurioStacksHandler stacks : this.curioInventory.asMap().values()) {

      if (stacks.isVisible()) {
        totalSlots += stacks.getSlots();
      }
    }
    return totalSlots;
